def main():
    with open(INDEX, encoding="utf-8") as f:
        idx = f.read()
    if idx.count(OLD_TS) != 4:
        raise SystemExit("expected 4 old timestamps, found %d" % idx.count(OLD_TS))
    idx = idx.replace(OLD_TS, TS)

    start = idx.find("        const forexData = {")
    end = idx.find("        /* ==========================================\n           B. Market metadata")
    if start < 0 or end < 0:
        raise SystemExit("forexData markers missing")
    idx = idx[:start] + "        const forexData = " + json.dumps(DATA, ensure_ascii=False, indent=4) + ";\n\n" + idx[end:]

    d0 = idx.find("        const dailyChanges = {")
    d1 = idx.find("        const macroDrivers = {")
    changes = {
        "EUR/USD": "-0.15%", "USD/JPY": "+0.09%", "AUD/USD": "+0.01%",
        "GBP/USD": "-0.30%", "EUR/JPY": "-0.06%", "GBP/JPY": "-0.21%",
    }
    idx = idx[:d0] + "        const dailyChanges = " + json.dumps(changes, ensure_ascii=False, indent=4) + ";\n\n" + idx[d1:]

    m0 = idx.find("        const macroDrivers = {")
    m1 = idx.find("        /* ==========================================\n           B2. News")
    if m0 < 0 or m1 < 0:
        raise SystemExit("macroDrivers markers missing")
    idx = idx[:m0] + "        const macroDrivers = " + json.dumps(DRIVERS, ensure_ascii=False, indent=4) + ";\n\n\n" + idx[m1:]

    needle = "            items: [\n"
    at = idx.find(needle)
    if at < 0:
        raise SystemExit("news items missing")
    idx = idx[:at + len(needle)] + NEWS_ITEM_JS + idx[at + len(needle):]

    s = idx.find("const forexData = {"); s2 = idx.find("{", s)
    e = idx.find("\n};", s) + len("\n};")
    parsed = json.loads(idx[s2:e][:-1].rstrip())
    assert list(parsed) == list(DATA)
    if idx.count(TS) != 4:
        raise SystemExit("timestamp count %d" % idx.count(TS))
    with open(INDEX, "w", encoding="utf-8", newline="\r\n") as f:
        f.write(idx)
    print("index.html patched")

    with open(LEDGER, encoding="utf-8") as f:
        ledger = json.load(f)
    assert ledger["watching"] == []
    assert any(t["pair"] == "GBP/USD" and t.get("entry") == 1.3376 for t in ledger["open"])
    # 28/10 close 1.3288 is between stop 1.346 and target 1.325 — open ticket is not modified
    ledger["meta"]["lastUpdated"] = "28/10/2026"
    with open(LEDGER, "w", encoding="utf-8", newline="\n") as f:
        json.dump(ledger, f, ensure_ascii=False, indent=2)
        f.write("\n")
    print("ledger lastUpdated only; GBP/USD open unchanged")

    with open(NEWS, encoding="utf-8") as f:
        news = f.read()
    news = news.replace("Market Wire · Euro Pins the 9-Month Low", "Market Wire · Fed Holds, Euro Makes a Second Low")
    news = news.replace("Telégrafo da Mesa · Euro Crava a Mínima de 9 Meses", "Telégrafo da Mesa · Fed Mantém, Euro Faz a Segunda Mínima")
    news = news.replace(OLD_TS, TS)
    old_fomc = '''                    <span class="cal-date">27-28/10</span>
                    <span class="cal-event"><span class="lang-en">FOMC — hold at 3.75-4.00% is the base case</span><span class="lang-pt" style="display:none;">FOMC — manutenção em 3,75-4,00% é o caso-base</span></span>'''
    new_fomc = '''                    <span class="cal-date">28/10</span>
                    <span class="cal-event"><span class="lang-en">FOMC held 3.75-4.00%, vote 10-2</span><span class="lang-pt" style="display:none;">FOMC manteve 3,75-4,00%, voto 10-2</span></span>'''
    old_cpi = '''                    <span class="cal-event"><span class="lang-en">Australian CPI — 00:30 UTC (ABS)</span><span class="lang-pt" style="display:none;">CPI australiano — 00:30 UTC (ABS)</span></span>'''
    new_cpi = '''                    <span class="cal-event"><span class="lang-en">Australia CPI 4.3% y/y, trimmed mean 3.6%</span><span class="lang-pt" style="display:none;">CPI australiano 4,3% a/a, média truncada 3,6%</span></span>'''
    if old_fomc not in news or old_cpi not in news:
        raise SystemExit("calendar cells missing")
    news = news.replace(old_fomc, new_fomc, 1).replace(old_cpi, new_cpi, 1)
    marker = "                <!-- News 27/10/2026:"
    if marker not in news:
        raise SystemExit("news marker missing")
    news = news.replace(marker, NEWS_CARD + marker, 1)
    with open(NEWS, "w", encoding="utf-8", newline="\n") as f:
        f.write(news)
    print("news.html patched")

    with open(SITEMAP, encoding="utf-8") as f:
        sm = f.read()
    n = sm.count("2026-10-27")
    if n != 9:
        raise SystemExit("expected 9 sitemap dates, found %d" % n)
    sm = sm.replace("2026-10-27", "2026-10-28")
    with open(SITEMAP, "w", encoding="utf-8", newline="\n") as f:
        f.write(sm)
    print("sitemap patched")

    with open(VERIFY, encoding="utf-8") as f:
        v = f.read()
    v = v.replace('TODAY_TS = "27/10/2026 21:19 UTC"', 'TODAY_TS = "%s"' % TS)
    v = v.replace(
        'TODAY_DATE = "27/10/2026"  # basis session date (report edition: 27/10/2026)',
        'TODAY_DATE = "28/10/2026"  # basis session date (report edition: 28/10/2026)')
    old_ticker = '''TICKER = [("EUR/USD","-0.34%"),("USD/JPY","+0.24%"),("AUD/USD","+0.11%"),
          ("GBP/USD","-0.15%"),("EUR/JPY","-0.11%"),("GBP/JPY","+0.09%")]'''
    new_ticker = '''TICKER = [("EUR/USD","-0.15%"),("USD/JPY","+0.09%"),("AUD/USD","+0.01%"),
          ("GBP/USD","-0.30%"),("EUR/JPY","-0.06%"),("GBP/JPY","-0.21%")]'''
    if old_ticker not in v:
        raise SystemExit("ticker block missing")
    v = v.replace(old_ticker, new_ticker)
    with open(VERIFY, "w", encoding="utf-8", newline="\n") as f:
        f.write(v)
    print("verify constants patched")

if __name__ == "__main__":
    main()
